/*
 * A039390  Numbers whose base-9 representation has the same nonzero number of
 *          6's and 7's.
 * https://oeis.org/A039390
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) is the n‑th positive integer whose base‑9 representation *
 *            contains the same nonzero number of 6's and 7's. The sequence is
 *            * generated by scanning integers in ascending order and
 *            selecting those * that satisfy this property
 * Range:     u8 n <= 6, u16 n <= 7662, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 66 terms through n = 8518 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include "../utils/mem.h"

/* check whether x (encoded as idx_t) satisfies the condition:
 * the same nonzero number of 6's and 7's in its base‑9 representation. */
static int has_equal_nonzero67(idx_t x)
{
    int count6 = 0, count7 = 0;
    while (x > 0) {
        int d = x % 9;
        if (d == 6) count6++;
        else if (d == 7) count7++;
        x /= 9;
    }
    return count6 == count7 && count6 > 0;
}

static seq_t *terms = NULL;     /* stored terms in increasing order */
static idx_t  term_count = 0;   /* number of stored terms */
static idx_t  term_cap   = 0;   /* capacity of the terms array */
static idx_t  next_to_test = 0; /* next integer to test for the property */

/* append a new term to the array, growing it if necessary */
static void append_term(seq_t value)
{
    if (term_count == term_cap) {
        idx_t new_cap = (term_cap == 0) ? 4 : term_cap * 2;
        seq_t *new_arr = mem_resize(seq_t, terms, new_cap);
        if (new_arr == NULL) abort(); /* out of memory */
        terms = new_arr;
        term_cap = new_cap;
    }
    terms[term_count++] = value;
}

/* return the n-th term of the sequence (offset 1). */
seq_t a(idx_t n)
{
    if (n == 0) return 0; /* undefined, but handle gracefully */

    /* generate terms until we have at least n of them */
    while (term_count < n) {
        next_to_test++;
        if (has_equal_nonzero67(next_to_test)) {
            append_term((seq_t)next_to_test);
        }
    }

    return terms[n - 1];
}
